// One-shot: insert a Contact link into the top navigation of every
// static marketing page under marketing-static-export/. Idempotent, so
// running twice is a no-op.
//
// The marketing site keeps the exact same nav markup on every page, so
// we can patch all of them with two targeted replacements:
//   - desktop <nav>: Contact after the FAQ link, same classes.
//   - mobile menu: Contact after the FAQ link, before the divider.
//
// Pages generated by scripts/build-guides.mjs already include Contact
// so they skip through this script with no change.

import { readFile, writeFile, readdir, stat } from "node:fs/promises";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const OUT = join(ROOT, "marketing-static-export");

// The nav link we want to add. Classes match the existing FAQ link byte
// for byte, so visually there is zero diff beyond the extra item.
const DESKTOP_FAQ =
  '<a class="rounded-lg px-3.5 py-2 text-sm font-semibold text-ink/70 transition hover:bg-sky/10 hover:text-ink" href="#faq">FAQ</a>';
const DESKTOP_FAQ_WITH_CONTACT =
  DESKTOP_FAQ +
  '<a class="rounded-lg px-3.5 py-2 text-sm font-semibold text-ink/70 transition hover:bg-sky/10 hover:text-ink" href="/contact">Contact</a>';

const MOBILE_FAQ = '<a href="#faq">FAQ</a>';
const MOBILE_FAQ_WITH_CONTACT = MOBILE_FAQ + '<a href="/contact">Contact</a>';

async function findHtmlFiles(dir, acc = []) {
  const entries = await readdir(dir);
  for (const name of entries) {
    const full = join(dir, name);
    const st = await stat(full);
    if (st.isDirectory()) {
      if (name === "_next" || name === "fonts") continue;
      await findHtmlFiles(full, acc);
    } else if (name === "index.html") {
      acc.push(full);
    }
  }
  return acc;
}

function patch(html) {
  // Desktop. Skip if Contact is already next to FAQ in the top nav.
  if (!html.includes(DESKTOP_FAQ_WITH_CONTACT)) {
    html = html.replace(DESKTOP_FAQ, DESKTOP_FAQ_WITH_CONTACT);
  }
  // Mobile. Only patch the FAQ link that precedes the divider, so we
  // do not re-insert if we have already run.
  const mobileWithDivider = MOBILE_FAQ + '<div class="divider"></div>';
  const mobileWithContactAndDivider =
    MOBILE_FAQ_WITH_CONTACT + '<div class="divider"></div>';
  if (!html.includes(mobileWithContactAndDivider)) {
    html = html.replace(mobileWithDivider, mobileWithContactAndDivider);
  }
  return html;
}

async function main() {
  const files = await findHtmlFiles(OUT);
  let touched = 0;
  for (const file of files) {
    const original = await readFile(file, "utf8");
    const next = patch(original);
    if (next !== original) {
      await writeFile(file, next);
      touched++;
    }
  }
  console.log("patched " + touched + " of " + files.length + " files");
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
